import { useState } from "react";

function Login() {

  const [usuario, setUsuario] = useState("");

  return (
    <div>
      <h2>Iniciar Sesión</h2>

      <input
        type="text"
        placeholder="Usuario"
        value={usuario}
        onChange={(e) => setUsuario(e.target.value)}
      />

      <br /><br />

      <input
        type="password"
        placeholder="Contraseña"
      />

      <br /><br />

      <button>Ingresar</button>

      <p>Usuario: {usuario}</p>

    </div>
  );
}

export default Login;
